cat > multicode/duckpit/build/onepit/iter8d/v6l/R2/analyze.py <<'E'
#!/usr/bin/env python3
# usage: analyze.py <dir> [<dir>...]  — по логам фермы: минуты глав I/II, предложения/взятые награды по видам, доля VIP и Турбо в доходе до конца главы.
import pathlib,re,json,statistics,sys
def med(a): return round(statistics.median(a),2) if a else None
out={}
for d in sys.argv[1:]:
  rows=[]
  for p in sorted(pathlib.Path(d).glob('*.log')):
    t=p.read_text(errors='replace')
    ph={int(c):float(l)/60 for c,_,l in re.findall(r'pit pass ch=(\d) t=([\d.]+) len=([\d.]+)',t)}
    ph_t={int(c):float(tt) for c,tt,_ in re.findall(r'pit pass ch=(\d) t=([\d.]+) len=([\d.]+)',t)}
    if not ph: continue
    offers={}
    for w in re.findall(r'hall rv offer who=(\w+)',t): offers[w]=offers.get(w,0)+1
    claims={}
    for w in re.findall(r'hall rv claim who=(\w+)',t): claims[w]=claims.get(w,0)+1
    vip=[(float(tt),float(u)) for u,tt in re.findall(r'vip sold usd=([\d.]+) total=[\d.]+ t=([\d.]+)',t)]
    led=[(float(m.group('t')),float(m.group('in')),float(m.group('turbo') or 0)) for m in re.finditer(r'ledger tag=minute .*?in=(?P<in>[\d.]+).*?(?:src_turbo=(?P<turbo>[\d.]+).*?)?t=(?P<t>[\d.]+) ch=',t)]
    # src_turbo может стоять не в позиции регэкспа выше — берём отдельно
    led=[]
    for l in re.findall(r'ledger tag=minute [^\n]*',t):
      g=lambda k: (re.search(k+r'=([\d.]+)',l) or [None,'0'])[1]
      led.append((float(g(' t')),float(g('in')),float(g('src_turbo'))))
    row=dict(run=p.stem,ch1=round(ph.get(1,0),2) or None,ch2=round(ph.get(2,0),2) or None,offers=offers,claims=claims,exceptions=len(re.findall('Exception',t)))
    for ch in (1,2):
      if ch not in ph_t: continue
      lo=ph_t.get(ch-1,0); hi=ph_t[ch]
      L=[x for x in led if x[0]<=hi]
      Lp=[x for x in led if x[0]<=lo]
      inc=(L[-1][1] if L else 0)-(Lp[-1][1] if Lp else 0)
      v=sum(u for tt,u in vip if lo<tt<=hi)
      tb=(L[-1][2] if L else 0)-(Lp[-1][2] if Lp else 0)
      row[f'vip_pct_ch{ch}']=round(100*v/inc,2) if inc>0 else None
      row[f'turbo_pct_ch{ch}']=round(100*tb/inc,2) if inc>0 else None
    rows.append(row)
  g={}
  for r in rows: g.setdefault(r['run'].split('_s')[0],[]).append(r)
  summ={}
  for k,v in g.items():
    s=dict(n=len(v))
    for key in ('ch1','ch2','vip_pct_ch1','turbo_pct_ch1','vip_pct_ch2','turbo_pct_ch2'):
      a=[r[key] for r in v if r.get(key​) is not None]
      if a: s[key​]=dict(median=med(a),min=round(min(a),2),max=round(max(a),2))
    s['exceptions']=sum(r['exceptions'] for r in v)
    summ[k]=s
  out[d]=dict(summary=summ,runs=rows)
  for k,s in summ.items(): print(d,k,json.dumps(s,ensure_ascii=False))
json.dump(out,open('/dev/stdout' if False else pathlib.Path(sys.argv[1]).parent/'analysis.json','w'),ensure_ascii=False,indent=1)
E
